"""Creates a Favorite from the first wall of the project with CreateFavoritesFromElements, then deletes it.

Needs at least one Wall.
"""
import aclib

walls = aclib.RunTapirCommand ('GetElementsByType', {'elementType': 'Wall'})['elements'][:1]
if not walls:
    raise SystemExit ('No wall in the project.')

aclib.PrintJson (aclib.RunTapirCommand ('CreateFavoritesFromElements', {
    'favoritesFromElements': [{
        'elementId': walls[0]['elementId'],
        'favorite': 'Tapir Example Wall'
    }]
}))

aclib.RunTapirCommand ('GetFavoritesByType', {'elementType': 'Wall'})

aclib.RunTapirCommand ('DeleteFavorites', {'favorites': ['Tapir Example Wall']})

"""Updates a Favorite from the settings of a wall with UpdateFavoritesFromElements.

Needs at least one Wall. The Favorite 'Tapir Example Wall' is created by the script and deleted at the end.
"""
import aclib

walls = aclib.RunTapirCommand ('GetElementsByType', {'elementType': 'Wall'})['elements'][:1]
if not walls:
    raise SystemExit ('No wall in the project.')

favoriteName = 'Tapir Example Wall'
aclib.RunTapirCommand ('CreateFavoritesFromElements', {
    'favoritesFromElements': [{'elementId': walls[0]['elementId'], 'favorite': favoriteName}]
})

aclib.PrintJson (aclib.RunTapirCommand ('UpdateFavoritesFromElements', {
    'favoritesFromElements': [{'elementId': walls[0]['elementId'], 'favorite': favoriteName}]
}))

aclib.RunTapirCommand ('DeleteFavorites', {'favorites': [favoriteName]})

"""Renames a Favorite with RenameFavorites.

Needs at least one Wall. The Favorite is created from the first wall by the script and deleted at the end.
"""
import aclib

walls = aclib.RunTapirCommand ('GetElementsByType', {'elementType': 'Wall'})['elements'][:1]
if not walls:
    raise SystemExit ('No wall in the project.')

aclib.RunTapirCommand ('CreateFavoritesFromElements', {
    'favoritesFromElements': [{'elementId': walls[0]['elementId'], 'favorite': 'Tapir Example Wall'}]
})

aclib.PrintJson (aclib.RunTapirCommand ('RenameFavorites', {
    'renames': [{'oldName': 'Tapir Example Wall', 'newName': 'Tapir Example Wall (renamed)'}]
}))

aclib.RunTapirCommand ('DeleteFavorites', {'favorites': ['Tapir Example Wall (renamed)']})

"""Reads the library part, GDL parameters and marker stored in the Door Favorites with GetFavoriteSettings.

Needs a Door Favorite.
"""
import aclib

doorFavorites = aclib.RunTapirCommand ('GetFavoritesByType', {'elementType': 'Door'})['favorites']
if not doorFavorites:
    raise SystemExit ('The project has no Door Favorite.')

response = aclib.RunTapirCommand ('GetFavoriteSettings', {'favorites': doorFavorites[:3]})
for settings in response['favoriteSettings']:
    if 'error' in settings:
        print (settings['error']['message'])
    else:
        print (settings['favorite'], settings.get ('libPart', {}).get ('name'), len (settings['parameters']), 'parameters')

"""Gives a Favorite the settings of another Favorite with ChangeFavorite.

Needs a Wall Favorite. The changed Favorite is a copy of the first Wall Favorite, created by the script and deleted at
the end; it gets the settings of the last Wall Favorite. Requires Archicad 29 or later.
"""
import aclib

wallFavorites = aclib.RunTapirCommand ('GetAllFavorites', {'elementType': 'Wall'})['favorites']
if not wallFavorites:
    raise SystemExit ('The project has no Wall Favorite.')

created = aclib.RunTapirCommand ('CreateFavorite', {
    'name': 'Tapir Example Favorite',
    'source': {'favoriteName': wallFavorites[0]['name']},
    'conflictPolicy': 'RenameNew'
})

aclib.PrintJson (aclib.RunTapirCommand ('ChangeFavorite', {
    'favoriteName': created['name'],
    'source': {'favoriteName': wallFavorites[-1]['name']}
}))

aclib.RunTapirCommand ('DeleteFavorites', {'favorites': [created['name']]})

"""Deletes a Favorite through the Favorite manager with DeleteFavoritesWithManager.

Needs at least one Wall. The deleted Favorite is created from the first wall by the script first;
the second, missing Favorite shows the error item. Requires Archicad 29 or later.
"""
import aclib

walls = aclib.RunTapirCommand ('GetElementsByType', {'elementType': 'Wall'})['elements'][:1]
if not walls:
    raise SystemExit ('No wall in the project.')

aclib.RunTapirCommand ('CreateFavoritesFromElements', {
    'favoritesFromElements': [{'elementId': walls[0]['elementId'], 'favorite': 'Tapir Example Wall'}]
})

# 'folderPath' is optional: without it the Favorite is found by name anywhere,
# with it only directly in that folder (here the root folder).
aclib.PrintJson (aclib.RunTapirCommand ('DeleteFavoritesWithManager', {
    'favorites': [
        {'name': 'Tapir Example Wall', 'folderPath': []},
        {'name': 'No Such Favorite'}
    ]
}))

"""Reads the element default stored in Favorites through the Favorite manager (Archicad 29 or newer), without
applying it or placing an element: element type, layer, element ID, folder, library part and GDL parameters,
the marker of every element type that has one and the sub-elements with their kinds (subTypes). A Favorite
without a marker has no 'marker' field, and a Favorite that cannot be read gets an error item.
"""
import aclib

favoriteNames = []
for elementType in ['Window', 'CurtainWall', 'Stair']:
    favoriteNames += aclib.RunTapirCommand ('GetFavoritesByType', {
        'elementType': elementType
    }).get ('favorites', [])[:1]

response = aclib.RunTapirCommand ('GetFavoriteDefaults', {
    'favorites': favoriteNames
})

for favoriteDefault in response['favoriteDefaults']:
    if 'error' in favoriteDefault:
        continue
    print (favoriteDefault['favorite'], favoriteDefault['elementType'], 'on layer', favoriteDefault['layerIndex'],
           'with', len (favoriteDefault['subElements']), 'sub-elements')
    for subElement in favoriteDefault['subElements']:
        print ('    ', subElement['elementType'], subElement['subTypes'])
